changeSet.sql:
CREATE TABLE IF NOT EXISTS role( role_cd_id UUID PRIMARY KEY, role_tx_name TEXT NOT NULL UNIQUE );
CREATE TABLE IF NOT EXISTS user_account( usac_cd_id UUID PRIMARY KEY, usac_tx_username TEXT NOT NULL, usac_tx_password TEXT NOT NULL, usac_nm_account_locked BOOLEAN NOT NULL DEFAULT FALSE, usac_nm_failed_login_attempts INTEGER NOT NULL DEFAULT 0, usac_dt_lock_until TIMESTAMP, usac_dt_last_login_at TIMESTAMP, usac_dt_created_at TIMESTAMP NOT NULL, usac_dt_updated_at TIMESTAMP );
CREATE TABLE IF NOT EXISTS user_credential( uscr_cd_id UUID PRIMARY KEY,
usac_cd_id UUID NOT NULL,
uscr_tx_credential TEXT UNIQUE NOT NULL,
uscr_tx_credential_type VARCHAR(50) NOT NULL,
CONSTRAINT fk_user_credentials_user FOREIGN KEY (usac_cd_id) REFERENCES user_account(usac_cd_id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS user_role( usac_cd_id UUID NOT NULL, role_cd_id UUID NOT NULL,
CONSTRAINT fk_user_role_user FOREIGN KEY (usac_cd_id) REFERENCES user_account(usac_cd_id) ON DELETE CASCADE,
CONSTRAINT fk_user_role_role FOREIGN KEY (role_cd_id) REFERENCES role(role_cd_id) ON DELETE CASCADE,
PRIMARY KEY(usac_cd_id, role_cd_id) );
CREATE UNIQUE INDEX IF NOT EXISTS ux_role_name ON role(role_tx_name);
CREATE UNIQUE INDEX IF NOT EXISTS ux_user_credentials_type_value ON user_credentials( uscr_tx_credential_type, uscr_tx_credential );
CREATE INDEX IF NOT EXISTS ix_user_credentials_user ON user_credentials(usac_cd_id);
CREATE INDEX IF NOT EXISTS ix_user_role_user ON user_role(usac_cd_id);
CREATE INDEX IF NOT EXISTS ix_user_role_role ON user_role(role_cd_id);
